import {EmptyState} from '@bloxwap/hig/react/status';
import {Button} from '@bloxwap/hig/react/button';
import {HIGProvider} from '@bloxwap/hig/react/provider';
import {Stack,Text} from '@bloxwap/hig/react/surface';
import '@bloxwap/hig/tokens/css';
import '@bloxwap/hig/react/css';
export default function Example(){
const [checked,setChecked]=useState(false),[value,setValue]=useState('buy'),[range,setRange]=useState(25),[open,setOpen]=useState(false),[amount,setAmount]=useState('0.01'),[message,setMessage]=useState('');
const [notices,setNotices]=useState([{id:'1',message:'Demo copied',severity:'success' as const}]);
const choices=[{value:'buy',label:'Buy'},{value:'sell',label:'Sell'}];const rows:{id:string;label:string;value:number}[]=[{id:'btc',label:'Bitcoin (BTC)',value:67234.56}];
const empty=false,busy=false,disabled=false,error=undefined;
return <HIGProvider density="comfortable"><Stack><EmptyState title='No open positions' description='Positions supplied by the host appear here.' action={<Button intent='secondary' onClick={()=>setMessage('Refresh requested')}>Refresh</Button>}/><Text>{message}</Text></Stack></HIGProvider>;
}

