import {View} from 'react-native';
import {FromPicker} from '@bloxwap/hig/native/recipes';
import {HIGProvider} from '@bloxwap/hig/native/provider';
import {Stack,Text} from '@bloxwap/hig/native/surface';

export default function Example(){
const [checked,setChecked]=useState(false),[value,setValue]=useState('buy'),[range,setRange]=useState(25),[open,setOpen]=useState(false),[amount,setAmount]=useState('0.01'),[message,setMessage]=useState('');
const [notices,setNotices]=useState([{id:'1',message:'Demo copied',severity:'success' as const}]);
const choices=[{value:'buy',label:'Buy'},{value:'sell',label:'Sell'}];const trigger=useRef<React.ComponentRef<typeof View>>(null);const rows:{id:string;label:string;value:number}[]=[{id:'btc',label:'Bitcoin (BTC)',value:67234.56}];
const empty=false,busy=false,disabled=false,error=undefined;
return <HIGProvider density="comfortable"><Stack><FromPicker wallet={{connected:true,address:'DMzeeNq7UYBu4tYbJdc3bVzBhXb32'}} onDisconnect={()=>setMessage('The host disconnects the wallet')} tokens={[{id:'1-eth',symbol:'ETH',name:'Ether',chain:'Ethereum',chainId:1,balance:0.42,price:3521.12},{id:'1-usdc',symbol:'USDC',name:'USD Coin',chain:'Ethereum',chainId:1,balance:1250.45,price:1},{id:'8453-usdc',symbol:'USDC',name:'USD Coin',chain:'Base',chainId:8453,balance:80.5,price:1}]} onSelect={token=>setMessage(`${token.name} on ${token.chain} selected`)}/><Text>{message}</Text></Stack></HIGProvider>;
}

